CREATE TABLE "RetailPriceObservation" ("id" UUID NOT NULL,"payloadHash" VARCHAR(64) NOT NULL,"productKey" VARCHAR(80) NOT NULL,"bindingHash" VARCHAR(64) NOT NULL,"identity" VARCHAR(220),"status" VARCHAR(20) NOT NULL,"originalPrice" DECIMAL(12,2),"currency" TEXT NOT NULL DEFAULT 'TWD',"priceType" VARCHAR(30),"sourceUrl" TEXT,"sourceTitle" TEXT,"sourceProductTitle" TEXT,"sourcePeriod" TEXT,"evidenceQuote" TEXT,"notes" TEXT,"checkedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RetailPriceObservation_pkey" PRIMARY KEY ("id"));
CREATE INDEX "RetailPriceObservation_productKey_status_expiresAt_idx" ON "RetailPriceObservation"("productKey","status","expiresAt");
CREATE INDEX "RetailPriceObservation_expiresAt_idx" ON "RetailPriceObservation"("expiresAt");
